targetPath = self.page.props.path.strip("/")

def findPath(items, parent=""):
    for i, item in enumerate(items):
        indexPath = parent + str(i)

        itemPath = item.get("data", {}).get("path", "").strip("/")

        # ✅ Match full path
        if itemPath == targetPath:
            return indexPath

        # ✅ Recursive search
        if item.get("items"):
            result = findPath(item["items"], indexPath + "/")
            if result:
                return result

    return None


treeItems = self.props.items

found = findPath(treeItems)

if found:
    return found

return None
